const finalizeStore = (data) => {
  const id = "store-" + Date.now();
  // Step 2 products land in the store catalog as live records (Epic A).
  const carried = (data.curatedProducts || []).map((c, i) => ({
    ...c,
    id: "prod-" + id + "-" + i,
    status: "live",
    ready: true,
    teamSetting: c.teamSetting || "fan-gear",
    optRequired: c.optRequired ?? c.teamSetting === "team-required",
    optSupplied: c.optSupplied ?? c.teamSetting === "team-supplied",
    pricing: c.pricing || defaultPricing(),
  }));
  const newStore = {
    id, ...data,
    products: carried,
    pendingProducts: [],
    __fresh: true,
    __userCreated: true, // persisted to localStorage so the store survives reloads
    ownership: "mine", // created by the active session user
    revenue: 0,
  };
  setStores((s) => [...s, newStore]);
  setActiveStoreId(id);
  setDashboardTab(carried.length ? "products" : "general");
  setScreen("dashboard");

// ─────────── Created-store persistence ───────────
// User-created stores survive a reload: they serialize into localStorage on
// every change (React-element fields stripped) and rehydrate on boot.
const CREATED_STORES_KEY = "ts_created_stores_v1";
function loadCreatedStores() {
  try {
    const raw = JSON.parse(localStorage.getItem(CREATED_STORES_KEY) || "[]");
    return Array.isArray(raw) ? raw.map((s) => ({ ...s, __fresh: false })) : [];
  } catch (e) { return []; }
}
function saveCreatedStores(list) {
  try {
    localStorage.setItem(CREATED_STORES_KEY, JSON.stringify(list, (k, v) => {
      if (k === "thumbnail") return undefined; // React elements don't serialize
      if (v && typeof v === "object" && v.$$typeof) return undefined;
      return v;
    }));
  } catch (e) {}
}

function App() {
  const [tweaks, setTweak] = useTweaks(TWEAK_DEFAULTS);

const [stores, setStores] = React.useState(() => (frameRoute ? makeSeededStores() : makeSeededStores().concat(loadCreatedStores())));
const [activeStoreId, setActiveStoreId] = React.useState(null);
// Persist user-created stores (and any edits to them) across reloads.
React.useEffect(() => { if (!frameRoute) saveCreatedStores(stores.filter((s) => s.__userCreated)); }, [stores, frameRoute]);
